17	// Lowercase, minimal-width hex -- matches the bare hex a stripped "0x" address
18	// yields, so a symbol and its literal address resolve to the same string.
19	std::string to_hex(uint64_t v) {
20	  std::ostringstream ss;
21	  ss << std::hex << v;
22	  return ss.str();
23	}
