25	bool slurp(const std::string& path, std::vector<char>& buf) {
26	  std::ifstream f(path, std::ios::binary);
27	  if (!f) return false;
28	  std::ostringstream ss;
29	  ss << f.rdbuf();
30	  const std::string s = ss.str();
31	  buf.assign(s.begin(), s.end());
32	  return true;
33	}
