67	std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
68	                       std::string& err) {
69	  err.clear();
70	
71	  // A "0x"/"0X" address is used verbatim with the prefix stripped (roi.sh
72	  // `${boundary#0[xX]}`); the .symtab is never touched.
73	  if (boundary.starts_with("0x") || boundary.starts_with("0X")) {
74	    std::string addr = boundary.substr(2);
75	    // Must be all hex digits: a verbatim pass of e.g. "ZZZ"/"10zz" would let the
76	    // downstream strtoull silently truncate to 0x0/0x10 (wrong PC window).
77	    if (addr.empty() ||
78	        addr.find_first_not_of("0123456789abcdefABCDEF") != std::string::npos) {
79	      err = "malformed address '" + boundary + "'";
80	      return "";
81	    }
82	    return addr;
83	  }
84	
85	  std::vector<char> buf;
86	  Elf64_Ehdr eh;
87	  if (!read_elf64_header(elf_path, buf, eh, err)) return "";
88	
89	  // Scan section headers for a symbol table; resolve names through its linked
90	  // string table (sh_link).
91	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
92	    Elf64_Shdr sym_sh;
93	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
94	      break;
95	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
96	
97	    Elf64_Shdr str_sh;
98	    if (sym_sh.sh_link >= eh.e_shnum ||
99	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
100	              str_sh))
101	      continue;
102	
103	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
104	    for (size_t s = 0; s < nsym; ++s) {
105	      Elf64_Sym sym;
106	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
107	      if (sym.st_shndx == SHN_UNDEF) continue;  // --defined-only
108	
109	      const size_t noff = str_sh.sh_offset + sym.st_name;
110	      if (noff >= buf.size()) continue;
111	      const char* name = buf.data() + noff;
112	      const size_t avail = buf.size() - noff;
113	      if (::strnlen(name, avail) == avail) continue;  // unterminated in bounds
114	      if (boundary == name) return to_hex(sym.st_value);
115	    }
116	  }
117	
118	  err = "symbol '" + boundary + "' not defined in " + elf_path;
119	  return "";
120	}
