136	uint64_t elf_load_top(const std::string& elf_path, std::string& err) {
137	  std::vector<char> buf;
138	  Elf64_Ehdr eh;
139	  if (!read_elf64_header(elf_path, buf, eh, err)) return 0;
140	  // Top of the static image: the highest (p_paddr + p_memsz) over PT_LOAD.
141	  // p_paddr is the guest-physical placement (== p_vaddr for the identity-mapped
142	  // bare-metal fixtures), the space the V-scratch GPA also lives in.
143	  uint64_t top = 0;
144	  for (uint16_t i = 0; i < eh.e_phnum; ++i) {
145	    Elf64_Phdr ph;
146	    const size_t off = static_cast<size_t>(eh.e_phoff) +
147	                       static_cast<size_t>(i) * eh.e_phentsize;
148	    if (!load(buf, off, ph)) {
149	      err = "truncated program header table in '" + elf_path + "'";
150	      return 0;
151	    }
152	    if (ph.p_type != PT_LOAD) continue;
153	    const uint64_t end = ph.p_paddr + ph.p_memsz;
154	    if (end > top) top = end;
155	  }
156	  return top;  // 0 (empty err) when the ELF has no loadable segments
157	}
