159	std::string symbolize(const std::string& elf_path, uint64_t addr) {
160	  std::vector<char> buf;
161	  Elf64_Ehdr eh;
162	  std::string ignored;  // symbolize never errors -- empty result is the signal
163	  if (!read_elf64_header(elf_path, buf, eh, ignored)) return "";
164	
165	  // Track the highest-valued FUNC symbol whose range covers addr (st_value <=
166	  // addr < st_value + st_size), falling back to the nearest preceding FUNC
167	  // when sizes are absent.
168	  std::string best_name;
169	  uint64_t best_value = 0;
170	  bool found = false;
171	
172	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
173	    Elf64_Shdr sym_sh;
174	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
175	      break;
176	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
177	
178	    Elf64_Shdr str_sh;
179	    if (sym_sh.sh_link >= eh.e_shnum ||
180	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
181	              str_sh))
182	      continue;
183	
184	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
185	    for (size_t s = 0; s < nsym; ++s) {
186	      Elf64_Sym sym;
187	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
188	      if (sym.st_shndx == SHN_UNDEF) continue;
189	      if (ELF64_ST_TYPE(sym.st_info) != STT_FUNC) continue;
190	      if (sym.st_value > addr) continue;
191	      // With a size, require coverage; without, accept as a preceding label.
192	      if (sym.st_size != 0 && addr >= sym.st_value + sym.st_size) continue;
193	      if (found && sym.st_value <= best_value) continue;
194	
195	      const size_t noff = str_sh.sh_offset + sym.st_name;
196	      if (noff >= buf.size()) continue;
197	      const char* name = buf.data() + noff;
198	      const size_t avail = buf.size() - noff;
199	      if (::strnlen(name, avail) == avail) continue;
200	
201	      best_name = name;
202	      best_value = sym.st_value;
203	      found = true;
204	    }
205	  }
206	
207	  if (!found) return "";
208	  const uint64_t off = addr - best_value;
209	  if (off == 0) return best_name;
210	  std::ostringstream ss;
211	  ss << best_name << "+0x" << std::hex << off;
212	  return ss.str();
213	}
